package br.com.cineo;
import java.io.*;import java.nio.file.*;import org.json.*;
public class CacheCheck {
 static int checks=0;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{MainActivity a=new MainActivity(Files.createTempDirectory("cineo-cache-test").toFile());FastCache cache=new FastCache(a);String scope=cache.scope();JSONObject data=new JSONObject().put("items",new JSONArray().put(new JSONObject().put("id",3)));cache.put(scope,"/v9/start",data,cache.epoch);long start=System.nanoTime();check(cache.get(scope,"/v9/start").value().getJSONArray("items").length()==1,"Warm cache must contain the catalogue");long micros=(System.nanoTime()-start)/1000;
 FastCache cold=new FastCache(a);check(cold.get(scope,"/v9/start")!=null,"Snapshot must survive memory reset");a.uid="account-b";check(cold.get(cold.scope(),"/v9/start")==null,"Other accounts must never see the snapshot");a.uid="account-a";a.viewerId="child";a.viewerKids=true;check(cold.get(cold.scope(),"/v9/start")==null,"Viewer boundaries must isolate snapshots");a.viewerKids=false;a.viewerId="";
 cache.put(scope,"/v8/ops/backups",data,cache.epoch);check(cache.get(scope,"/v8/ops/backups")==null,"Admin data must not be cached");cache.put(scope,"/v7/devices",data,cache.epoch);check(cache.get(scope,"/v7/devices")==null,"Device/session data must not be cached");cache.put(scope,"/v9/catalog?before=10",new JSONObject().put("token","forbidden"),cache.epoch);check(cache.get(scope,"/v9/catalog?before=10")==null,"Auth responses must never be persisted");
 cache.put(scope,"/saved",data,cache.epoch);long prior=cache.epoch;cache.changed();check(cache.get(scope,"/v9/start")!=null,"A mutation must preserve the visible feed");check(System.currentTimeMillis()-cache.get(scope,"/v9/start").at>=FastCache.FRESH,"Changed feed must refresh in background");check(cache.get(scope,"/saved")==null,"Saved lists must refresh after mutations");cache.put(scope,"/saved",data,prior);check(cache.get(scope,"/saved")==null,"An old request must not repopulate invalidated data");
 cache.memory.put(scope+"|/v9/start",new FastCache.Entry(data.toString(),System.currentTimeMillis()-FastCache.MAX-100));check(cache.get(scope,"/v9/start")==null,"Expired snapshots must be rejected");cache.invalidate();check(new FastCache(a).get(scope,"/v9/start")==null,"Logout/clear must erase persistent snapshots");System.out.println("Cache checks passed: "+checks+"; warm read: "+micros+" microseconds (local JVM, not a phone benchmark)");}
}
